        self._order = []  # insertion order of job_ids
        self._token_counter = 0

    def _next_token(self):
        self._token_counter += 1
        return str(self._token_counter)

    def add(self, job_id):
        with self._lock:
            if job_id not in self._jobs:
                self._jobs[job_id] = {
                    'state': 'queued',
                    'expiry': None,
                    'worker': None,
                    'token': None,
                }
                self._order.append(job_id)

    def _find_eligible(self):
        """Find the first eligible job in insertion order. Must hold lock."""
        for job_id in self._order:
            rec = self._jobs[job_id]
            if rec['state'] in ('queued', 'running'):
                if rec['expiry'] is None or rec['expiry'] <= 0:
                    return job_id
                # For running jobs, check expiry
                if rec['state'] == 'running' and rec['expiry'] is not None and rec['expiry'] <= 0:
                    return job_id
        return None

    def claim(self, worker, now, ttl):
        if ttl <= 0:
            return None
        with self._lock:
            # Find eligible job: queued or running whose expiry <= now
            target_id = None
            for job_id in self._order:
                rec = self._jobs[job_id]
                if rec['state'] in ('queued', 'running'):
                    if rec['expiry'] is None or rec['expiry'] <= now:
                        target_id = job_id
                        break
            if target_id is None:
                return None
            rec = self._jobs[target_id]
            token = self._next_token()
            rec['state'] = 'running'
            rec['expiry'] = now + ttl
            rec['worker'] = worker
            rec['token'] = token
            return {'job_id': target_id, 'worker': worker, 'token': token}

    def renew(self, lease, now, ttl):
