            return False
        with self._lock:
            target_id = lease.get('job_id')
            if target_id is None or target_id not in self._jobs:
                return False
            rec = self._jobs[target_id]
            # Must match exact current token and worker
            if rec['worker'] != lease.get('worker') or rec['token'] != lease.get('token'):
                return False
            # expiry must be > now
            if rec['expiry'] is None or rec['expiry'] <= now:
                return False
            # Extend expiry
            rec['expiry'] = now + ttl
            return True

